import inspect
import math
from statistics import median


def run(api):
    """Resume the existing trial; do not reset the simulator."""
    if api.done():
        return

    def signature(fn):
        try:
            return inspect.signature(fn)
        except (TypeError, ValueError):
            return None

    move_sig = signature(api.move_to)

    def position_move(xyz, extra=None):
        kwargs = dict(extra or {})
        if move_sig is not None:
            p = move_sig.parameters.get("xyz")
            if p is not None and p.kind == inspect.Parameter.KEYWORD_ONLY:
                return api.move_to(xyz=list(xyz), **kwargs)
        return api.move_to(list(xyz), **kwargs)

    # Find the supported orientation interface rather than repeating the
    # rejected move_to(..., yaw=...) call.
    yaw_parameter = None
    if move_sig is not None:
        for name in ("yaw_deg", "yaw_degrees", "yaw_rad", "yaw"):
            p = move_sig.parameters.get(name)
            if p is not None:
                yaw_parameter = p
                break

    def angle_value(degrees, name, fn):
        text = (inspect.getdoc(fn) or "").lower()
        if "rad" in name.lower():
            return math.radians(degrees)
        if "deg" in name.lower():
            return degrees
        if "radian" in text and "degree" not in text:
            return math.radians(degrees)
        return degrees

    rotation_fn = None
    rotation_relative = False
    rotation_parameter = None

    if yaw_parameter is None:
        for name in (
            "set_yaw_deg", "set_yaw", "set_tool_yaw", "set_peg_yaw",
            "rotate_to_yaw", "rotate_yaw", "rotate_tool_yaw",
        ):
            fn = getattr(api, name, None)
            if not callable(fn):
                continue
            sig = signature(fn)
            if sig is None:
                continue
            params = [
                p for p in sig.parameters.values()
                if p.kind not in (
                    inspect.Parameter.VAR_POSITIONAL,
                    inspect.Parameter.VAR_KEYWORD,
                )
            ]
            angle_params = [
                p for p in params
                if any(s in p.name.lower()
                       for s in ("yaw", "angle", "deg", "rad", "delta"))
            ]
            if not angle_params and len(params) == 1:
                angle_params = params
            if not angle_params:
                continue
            p = angle_params[0]
            if any(q is not p and q.default is inspect.Parameter.empty
                   for q in params):
                continue

            rotation_fn = fn
            rotation_parameter = p
            doc = (inspect.getdoc(fn) or "").lower()
            rotation_relative = (
                "delta" in p.name.lower()
                or "relative" in doc
                or (name.startswith("rotate_") and "to_yaw" not in name
                    and "absolute" not in doc)
            )
            break

    if yaw_parameter is None and rotation_fn is None:
        raise RuntimeError(
            "No supported yaw-control interface was found. "
            "Translation alone cannot align this square peg."
        )

    # Optional measured-position feedback. Never use an IK residual as a
    # substitute for the achieved TCP position.
    def extract_xyz(value):
        if isinstance(value, dict):
            for key in ("tcp", "tcp_pose", "tcp_position", "xyz",
                        "position", "pose"):
                if key in value:
                    result = extract_xyz(value[key])
                    if result is not None:
                        return result
            return None
        if isinstance(value, (str, bytes)):
            return None
        try:
            if len(value) >= 3:
                xyz = [float(value[i]) for i in range(3)]
                if all(math.isfinite(v) for v in xyz):
                    return xyz
        except (TypeError, ValueError, IndexError):
            pass
        try:
            return extract_xyz(value[0])
        except (TypeError, KeyError, IndexError):
            return None

    position_reader = None
    for name in (
        "get_tcp_pose", "tcp_pose", "get_tcp_position", "tcp_position",
        "get_pose", "get_state", "state", "tcp",
    ):
        attr = getattr(api, name, None)
        if attr is None:
            continue
        if callable(attr):
            sig = signature(attr)
            if sig is not None:
                try:
                    sig.bind()
                except TypeError:
                    continue
            reader = attr
        else:
            reader = lambda name=name: getattr(api, name)

        try:
            measured = extract_xyz(reader())
        except (TypeError, ValueError, AttributeError):
            continue
        if measured is not None:
            position_reader = reader
            break

    def tcp():
        return extract_xyz(position_reader()) if position_reader else None

    # These are the robust estimates from the nine observations already
    # collected. In particular, do not clip the measured yaw to +/-15 deg.
    cx = 0.4612203569138539
    cy = -0.04672282503879515
    hole_yaw = -34.00458284262519
    top = 0.05
    clearance_z = top + 0.02
    target_z = top - 0.032

    current_angle = None
    relative_angle = 0.0

    def move(xyz):
        if yaw_parameter is None or current_angle is None:
            return position_move(xyz)

        p = yaw_parameter
        value = angle_value(current_angle, p.name, api.move_to)
        if p.kind == inspect.Parameter.POSITIONAL_ONLY:
            positional = [
                q for q in move_sig.parameters.values()
                if q.kind in (inspect.Parameter.POSITIONAL_ONLY,
                              inspect.Parameter.POSITIONAL_OR_KEYWORD)
            ]
            if len(positional) < 2 or positional[1].name != p.name:
                raise RuntimeError("Unsupported positional yaw signature.")
            return api.move_to(list(xyz), value)
        return position_move(xyz, {p.name: value})

    def settle(xyz, attempts=5):
        for _ in range(attempts):
            move(xyz)
            if api.done():
                return True
            actual = tcp()
            if actual is not None:
                if max(abs(actual[i] - xyz[i]) for i in range(3)) < 0.00015:
                    return True
        return False

    def lift():
        actual = tcp()
        # Last observed TCP if the API does not expose position feedback.
        xy = actual[:2] if actual is not None else [cx, cy]
        settle([xy[0], xy[1], clearance_z])
        actual = tcp()
        if actual is not None and actual[2] < top + 0.008:
            raise RuntimeError("Retraction failed; refusing to rotate in contact.")

    def orient(angle):
        nonlocal current_angle, relative_angle
        if yaw_parameter is not None:
            current_angle = angle
            return

        command = angle
        if rotation_relative:
            # The initial absolute orientation may be unknown. Subsequent
            # commands track relative changes; the bounded 90-degree search
            # below covers all distinct square-peg orientations.
            command = (angle - relative_angle + 45.0) % 90.0 - 45.0
            relative_angle += command

        p = rotation_parameter
        value = angle_value(command, p.name, rotation_fn)
        if p.kind == inspect.Parameter.KEYWORD_ONLY:
            rotation_fn(**{p.name: value})
        else:
            rotation_fn(value)

    def insert(x, y):
        settle([x, y, clearance_z])
        actual = tcp()
        if actual is not None:
            if (actual[2] < top + 0.008
                    or math.hypot(actual[0] - x, actual[1] - y) > 0.0003):
                return False

        # The trace shows contact at TCP z=0.05: here the controlled point
        # behaves as the peg tip. Do not subtract the 80 mm peg length again.
        waypoints = [top + 0.010, top + 0.004, top + 0.002]
        waypoints += [top + 0.001 - 0.001 * i for i in range(34)]

        for z in waypoints:
            z = max(z, target_z)
            reached = settle([x, y, z], attempts=3)
            if api.done():
                return True

            actual = tcp()
            if actual is not None:
                if math.hypot(actual[0] - x, actual[1] - y) > 0.0006:
                    return False
                # A persistent gap between target and measured z is a jam.
                # Do not accumulate further downward commands.
                if not reached and actual[2] - z > 0.0006:
                    return False

        return bool(api.done())

    # Try the observed orientation first. The remaining candidates cover
    # one 90-degree period, not just the nominal test-cell yaw range.
    yaw_offsets = [0.0]
    for delta in range(2, 45, 2):
        yaw_offsets.extend((float(delta), float(-delta)))
    yaw_offsets.append(45.0)

    xy_offsets = [
        (0.0, 0.0),
        (-0.00025, 0.0), (0.00025, 0.0),
        (0.0, -0.00025), (0.0, 0.00025),
        (-0.00025, -0.00025), (-0.00025, 0.00025),
        (0.00025, -0.00025), (0.00025, 0.00025),
    ]

    for dx, dy in xy_offsets:
        for dyaw in yaw_offsets:
            if api.done():
                return
            lift()
            orient(hole_yaw + dyaw)
            if insert(cx + dx, cy + dy):
                return

    lift()
    raise RuntimeError("Bounded alignment search exhausted; peg left retracted.")
